import { test, expect } from '@playwright/test';

test.describe('Change Email Address', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/user_profile');
    await page.getByRole('button', { name: 'Login' }).click();
    await page.getByLabel('Email').fill('user@example.com');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: 'Submit' }).click();
  });

  test('should display confirmation step after changing email', async ({ page }) => {
    await page.getByLabel('New Email Address').fill('newemail@example.com');
    await page.getByRole('button', { name: 'Change Email' }).click();

    const confirmationMessage = await page.getByText('Please confirm your new email address.');
    expect(confirmationMessage).toBeVisible();
  });

  test('should successfully change email after confirmation', async ({ page }) => {
    await page.getByLabel('New Email Address').fill('newemail@example.com');
    await page.getByRole('button', { name: 'Change Email' }).click();

    await page.getByRole('button', { name: 'Confirm Email Change' }).click();

    const successMessage = await page.getByText('Your email address has been successfully changed.');
    expect(successMessage).toBeVisible();
  });
});
